import re
code = re.sub(r"<!--.*?-->", "", src, flags=re.S)
js = "\n".join(re.findall(r"<script[^>]*>(.*?)</script>", code, re.S))
js_nc = re.sub(r"//[^\n]*", "", js)
check("charset utf-8 and a viewport meta (phones)", lambda: re.search(r'<meta charset="?utf-8', code, re.I) and 'name="viewport"' in code)
check("a textarea#message with dir=\"auto\" and a #send button", lambda: re.search(r'<textarea[^>]*id="message"[^>]*>', code) and 'dir="auto"' in re.search(r'<textarea[^>]*>', code).group() and re.search(r'<button[^>]*id="send"', code))
check("messages get dir=auto (Arabic and French in one chat)", lambda: re.search(r"""\.dir\s*=\s*["']auto["']|setAttribute\(\s*["']dir["']\s*,\s*["']auto""", js_nc))
check("POSTs JSON to /chat", lambda: re.search(r"""fetch\(\s*["'`]/chat["'`]|["'`]/chat["'`]""", js_nc) and "JSON.stringify" in js_nc and "application/json" in js_nc)
check("keeps and sends the session id", lambda: "session_id" in js_nc and re.search(r"sessionId\s*=\s*\w+\.session_id", js_nc))
check("model output via textContent, never innerHTML", lambda: "textContent" in js_nc and "innerHTML" not in js_nc)
check("renders sources", lambda: re.search(r"\.sources", js_nc) and re.search(r"\.n\b", js_nc))
check("a confirm button posting to /chat/confirm", lambda: "/chat/confirm" in js_nc and "action_id" in js_nc)
check("button disabled while waiting, re-enabled in finally", lambda: re.search(r"disabled\s*=\s*true", js_nc) and re.search(r"finally\s*{[^}]*disabled\s*=\s*false", js_nc, re.S))
check("HTTP errors are handled (res.ok / catch)", lambda: re.search(r"\.ok\b", js_nc) and "catch" in js_nc)
check("no external scripts (works offline in the office)", lambda: not re.search(r"<script[^>]+src=[\"']https?:", code))
